def solve(I):
    import copy
    R,C=len(I),len(I[0])
    # find pluses: centers where pattern up/down/left/right ==3
    pluses=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if I[r][c]!=0 and I[r-1][c]==3 and I[r+1][c]==3 and I[r][c-1]==3 and I[r][c+1]==3:
                cells=[(r-1,c),(r+1,c),(r,c-1),(r,c+1),(r,c)]
                pluses.append({'center':(r,c),'digit':I[r][c],'cells':set(cells)})
    out=[row[:] for row in I]
    # check vertical obstruction by foreign plus cells
    def foreign_in_col(col, self_cells):
        return any((r,col) in p['cells'] for p in pluses for r in range(R)) or \
               any(I[r][col] not in (0,3) and (r,col) not in self_cells for r in range(R))
    for p in pluses:
        r,c=p['center']; d=p['digit']
        if d==0: continue
        blocked=False
        for rr in range(R):
            if (rr,c) not in p['cells'] and I[rr][c] not in (0,):
                blocked=True
        if blocked:
            # shift to nearest column with no nonzero cells except own
            best=None
            for off in range(1,C):
                for s in (1,-1):
                    nc=c+s*off
                    if 0<=nc<C:
                        colvals=[I[rr][nc] for rr in range(R) if (rr,nc) not in p['cells']]
                        if all(v==0 for v in colvals):
                            if best is None or off<best[0]:
                                best=(off,nc,s)
                            break
            off,nc,s=best
            for (rr,cc) in p['cells']:
                if out[rr][cc] not in (0,) or True:
                    out[rr][cc]=0 if I[rr][cc]!=0 or True else 0
            # actually erase regardless
            p['center']=(r,nc)
            p['cells']={(r-1,nc),(r+1,nc),(r,nc-1),(r,nc+1),(r,nc)}
    # erase old plus positions (from original input) that are no longer plus cells
    allcells=set().union(*[p['cells'] for p in pluses])
    for r in range(R):
        for c in range(C):
            if (r,c) not in allcells and I[r][c] in (3,) :
                # only erase if it belonged to a plus originally
                pass
    # simpler: rebuild from scratch
    out=[[0]*C for _ in range(R)]
    # draw plus cells
    for p in pluses:
        r,c=p['center']; d=p['digit']
        out[r][c]=d
        for (rr,cc) in p['cells']:
            if (rr,cc)!=(r,c): out[rr][cc]=3
    # vertical lines
    for p in pluses:
        r,c=p['center']; d=p['digit']
        for rr in range(R):
            if out[rr][c]==0:
                out[rr][c]=d
    # horizontal lines fill remaining 0s
    for p in pluses:
        r,c=p['center']; d=p['digit']
        for cc in range(C):
            if out[r][cc]==0:
                out[r][cc]=d
    return out

