def build():
    out=[[0]*C for _ in range(R)]
    for p in pluses:
        out[p['r']][p['c']]=p['d']
        for cell in p['cells']:
            if cell!=(p['r'],p['c']): out[cell[0]][cell[1]]=3
    # vertical beams (digit pluses): stop at foreign 3-cells; pass through own 3s
    for p in pluses:
        if p['d']==0: continue
        fc=foreign_cells(p)
        for s in (1,-1):
            r0=p['r']
            rr=r0
            while 0<=rr+s<R:
                rr+=s
                cell=(rr,p['c'])
                if cell in fc and out[rr][p['c']]==3: break
                if out[rr][p['c']]!=3: out[rr][p['c']]=p['d']
    # horizontal beams: fill only 0 cells, stop at foreign 3-cells, pass own arms
    for p in pluses:
        if p['d']==0: continue
        fc=foreign_cells(p)
        for s in (1,-1):
            cc=p['c']
            while 0<=cc+s<C:
                cc+=s
                cell=(p['r'],cc)
                if cell in fc and out[p['r']][cc]==3: break
                if out[p['r']][cc]==0: out[p['r']][cc]=p['d']
    # blank vertical last: erase (0) all non-3 cells in its column
    for p in pluses:
        if p['d']==0:
            for rr in range(R):
                if out[rr][p['c']]!=3: out[rr][p['c']]=0
    return out

